import sys
f=sys.argv[1]; s=open(f,encoding='utf-8').read()
def sub(a,b,n=1):
    global s; assert s.count(a)==n,(a[:90],s.count(a)); s=s.replace(a,b)
sub("await say(['วันศุกร์\\nสะโพกซ้ายตื่นก่อนผม','รอยช้ำสีม่วง ขนาดเท่าฝ่ามือ\\nอยู่ในที่ที่เสื้อผ้าปิดได้ ถือว่าโชคดี']);",
    "await say(['วันศุกร์ สะโพกซ้ายตื่นก่อนผม\\nรอยช้ำสีม่วงเท่าฝ่ามือ อยู่ในที่ที่เสื้อผ้าปิดได้ ถือว่าโชคดี']);")
sub("await say(['\"เหล่าหลี่ กินยาเช้าหรือยังคะ\"\\n\"กำลังจะกิน\"','\"งั้นหนูรอนะคะ\"']); $('#cimg').src=src('pills_am');",
    "await say(['\"เหล่าหลี่ กินยาเช้าหรือยังคะ\"\\n\"กำลังจะกิน\" \"งั้นหนูรอนะคะ\"']); $('#cimg').src=src('pills_am');")
sub("await say(['คำนี้ออกมาเอง\\nเหมือนมือที่วางตะเกียบสองคู่','\"วันนี้บ่ายสองครึ่ง จะมีเภสัชกรมาเยี่ยมที่บ้านนะคะ สำนักงานประกันฯ ส่งมา\\nหนูขอแลกเวรไว้แล้ว จะกลับไปเปิดประตูให้ สี่โมงค่อยไปเข้าเวรดึก\"','\"ไม่ต้องมา ผมสบายดี\"\\n\"เขามาคุยเรื่องยาเฉยๆ ค่ะ ไม่ได้มาจับผิด\"','ผมวางหู\\nคนที่บอกว่าไม่ได้มาจับผิด ผมเจอมาทั้งชีวิต']); cardOff();\n  await say(['มีการตรวจเยี่ยม\\nต้องเตรียมที่ตั้ง']);",
    "await say(['\"บ่ายสองครึ่งจะมีเภสัชกรมาเยี่ยมที่บ้านนะคะ หนูแลกเวรไว้แล้ว จะกลับไปเปิดประตูให้\"\\n\"ไม่ต้องมา ผมสบายดี\" \"เขามาคุยเรื่องยาเฉยๆ ค่ะ ไม่ได้มาจับผิด\"','ผมวางหู คนที่บอกว่าไม่ได้มาจับผิด ผมเจอมาทั้งชีวิต\\nมีการตรวจเยี่ยม ต้องเตรียมที่ตั้ง']); cardOff();")
sub("let left=[['ใส่เสื้อแขนยาวทับ','สามสิบสี่องศา กับเสื้อแขนยาว\\nรอยช้ำไม่ได้อยู่ที่แขน แต่ผมรู้สึกว่าต้องปิดอะไรสักอย่าง'],['ดันลิ้นชักยาให้ปิดสนิท','สิบสามซอง ดันเข้าไปจนลิ้นชักปิดได้\\nสิ่งที่ตรวจไม่พบ ถือว่าไม่มี'],['ซ่อนหม้อข้าวต้มไว้หลังกระติกน้ำ','ต้มไว้ตั้งแต่วันอาทิตย์ วันนี้วันศุกร์\\nผมไม่ได้เปิดฝาดู']];",
    "let left=[['ใส่เสื้อแขนยาวทับ','สามสิบสี่องศากับเสื้อแขนยาว รอยช้ำไม่ได้อยู่ที่แขน แต่ต้องปิดอะไรสักอย่าง'],['ดันลิ้นชักยาให้ปิดสนิท','สิ่งที่ตรวจไม่พบ ถือว่าไม่มี'],['ซ่อนหม้อข้าวต้มไว้หลังกระติกน้ำ','ต้มไว้ตั้งแต่วันอาทิตย์ ผมไม่ได้เปิดฝาดู']];")
sub("await say(['ที่ตั้งพร้อมรับการตรวจ\\nผมนั่งรอตั้งแต่เที่ยง','บ่ายสองสิบห้า ผมต้องไปห้องน้ำ\\nไม่อยากให้พวกเขามาถึงตอนผมไม่อยู่ประจำที่ ผมเลยรีบ']);",
    "await say(['ผมนั่งรอตั้งแต่เที่ยง บ่ายสองสิบห้าต้องไปห้องน้ำ\\nไม่อยากให้พวกเขามาถึงตอนผมไม่อยู่ประจำที่ ผมเลยรีบ']);")
sub("await say(['กลับถึงเตียงพอดี\\nหน้าอกถูกนั่งทับเต็มน้ำหนัก ลมเข้าได้แค่ครึ่งเดียว']); sfx.knock();\n  await say(['เสียงเคาะประตู']); await show('door',1800); sfx.bark(); clock('14:30');\n  await say(['อาเหมยเปิดประตู\\nคนเสื้อขาวสองคน คนหนึ่งผมหงอกแซม อีกคนยังเด็กมาก','ผมพยายามนั่งตัวตรง จะรายงานตัว\\nแต่ลมไม่พอจะพูดสักคำ']);",
    "await say(['กลับถึงเตียงพอดี ลมเข้าได้แค่ครึ่งเดียว']); sfx.knock(); await show('door',1800); sfx.bark(); clock('14:30');\n  await say(['อาเหมยเปิดประตู คนเสื้อขาวสองคน คนหนึ่งผมหงอกแซม อีกคนยังเด็กมาก\\nผมจะนั่งตัวตรงรายงานตัว แต่ลมไม่พอจะพูดสักคำ']);")
sub("await say(['เด็กคนนั้นเห็นผมหอบ แล้วหันไปหาอาเหมย\\n\"คุณปู่เป็นแบบนี้บ่อยไหมครับ ปกติท่านใช้ยาพ่นตัวไหน\"','อาเหมยตอบแทนผม\\nผมนั่งอยู่ตรงนี้ ห่างไปสองก้าว เหมือนตู้ใบหนึ่ง']); trust(-1);\n  await say(['เภสัชกรผมหงอกแตะแขนเด็กคนนั้นเบาๆ ไม่ได้พูดอะไร\\nเด็กคนนั้นหน้าแดง แล้วหันกลับมาหาผม','มือผมควานหายาพ่น\\nได้อันสีเขียว']);",
    "await say(['เด็กคนนั้นเห็นผมหอบ แล้วหันไปถามอาเหมย \"คุณปู่เป็นแบบนี้บ่อยไหมครับ\"\\nอาเหมยตอบแทนผม ผมนั่งอยู่ห่างไปสองก้าว เหมือนตู้ใบหนึ่ง']); trust(-1);\n  await say(['เภสัชกรผมหงอกแตะแขนเด็กคนนั้นเบาๆ เขาหน้าแดง แล้วหันกลับมาหาผม\\nมือผมควานหายาพ่น ได้อันสีเขียว']);")
sub("await say(['เขาไม่ได้ยืนค้ำหัวผม\\nเขาคุกเข่าลงบนพื้น จนตาอยู่ระดับเดียวกับตาผม','\"ขอโทษครับคุณปู่ ผมควรถามคุณปู่เอง\"\\n\"อันสีฟ้าครับ ค่อยๆ\" เขาไม่ได้แย่งอันสีเขียวไปจากมือผม เขาแค่ยื่นอันสีฟ้ามา แล้วรอ']);",
    "await say(['เขาคุกเข่าลงบนพื้น จนตาอยู่ระดับเดียวกับตาผม\\n\"ขอโทษครับคุณปู่ ผมควรถามคุณปู่เอง\"','\"อันสีฟ้าครับ ค่อยๆ\"\\nเขาไม่ได้แย่งอันสีเขียวไปจากมือผม เขาแค่ยื่นอันสีฟ้ามา แล้วรอ']);")
sub("await hold('กดค้าง<br>หายใจออก',3000,''); $('#vig').style.opacity=.3;\n  await say('\"อีกครั้งครับ ช้ากว่าเดิม\"',{stay:1}); await hold('กดค้าง<br>หายใจออก',3600,''); $('#vig').style.opacity=0;\n  await say(['\"ดีมากครับ ไม่ต้องรีบ เรามีเวลาทั้งบ่าย\"','เรามีเวลาทั้งบ่าย\\nไม่มีใครพูดประโยคนี้กับผมมานานแล้ว หมอมีให้ผมสามนาที']); trust(1);",
    "await hold('กดค้าง<br>หายใจออก',3600,''); $('#vig').style.opacity=0;\n  await say(['\"ดีมากครับ ไม่ต้องรีบ เรามีเวลาทั้งบ่าย\"\\nไม่มีใครพูดประโยคนี้กับผมมานานแล้ว หมอมีให้ผมสามนาที']); trust(1);")
sub("await say(['\"ผมขอแนะนำตัวใหม่นะครับ\" เขาชูบัตรที่ห้อยคอให้ผมดูใกล้ๆ\\n\"ผมเป็นนักศึกษาเภสัช มากับเภสัชกรเฉิน วันนี้ขอรบกวนเวลาคุณปู่ราวหนึ่งชั่วโมง มาช่วยดูเรื่องยาครับ\"','\"คุณปู่อนุญาตไหมครับ\"\\nเขาถาม ในห้องของผมเอง ว่าผมอนุญาตไหม']);",
    "await say(['\"ผมขอแนะนำตัวใหม่นะครับ\" เขาชูบัตรให้ผมดูใกล้ๆ\\n\"ผมเป็นนักศึกษาเภสัช มากับเภสัชกรเฉิน ขอเวลาคุณปู่ราวหนึ่งชั่วโมง มาช่วยดูเรื่องยา คุณปู่อนุญาตไหมครับ\"']);")
sub("await say(['\"ต้องถอดรองเท้าไหมครับ\"\\nสามสิบปี ไม่เคยมีใครถามผมเรื่องนี้']); trust(1);\n  await say(['ผมเคยเจอคนถือแฟ้มมาหลายแบบ\\nบางคนเปิดถุงยาที่แขวนหลังประตู ก่อนจะทักผมด้วยซ้ำ','บางคนพาอาเหมยออกไปคุยที่ระเบียง\\nบางคนนั่งลงบนเตียงผม แล้วถามเลยว่า กินยาอะไรบ้าง','มีคนหนึ่งลูบหัวเจ้าดำอยู่นาน โดยไม่มองหน้าผมสักครั้ง\\nเจ้าดำชอบเขา ผมไม่']);",
    "await say(['\"ต้องถอดรองเท้าไหมครับ\"\\nสามสิบปี ไม่เคยมีใครถามผมเรื่องนี้','คนถือแฟ้มบางคนเปิดถุงยาหลังประตูก่อนจะทักผม บางคนพาอาเหมยไปคุยที่ระเบียง\\nบางคนลูบหัวเจ้าดำอยู่นานโดยไม่มองหน้าผม เจ้าดำชอบเขา ผมไม่']); trust(1);")
sub("await say(['เภสัชกรเฉินนั่งลงบนเก้าอี้ เด็กคนนั้นนั่งพื้นเหมือนเดิม\\nเขาเปิดสมุด แต่ยังไม่จดอะไร','\"คุณปู่อยู่ห้องนี้มานานหรือยังครับ\"']);",
    "await say(['เด็กคนนั้นนั่งพื้นเหมือนเดิม เปิดสมุด แต่ยังไม่จดอะไร\\n\"คุณปู่อยู่ห้องนี้มานานหรือยังครับ\"']);")
sub("await say(a===0?['\"สามสิบปี\" เขาทวน \"งั้นคุณปู่รู้จักตึกนี้ดีกว่าใครเลยนะครับ\"\\nประโยคธรรมดา แต่ไม่มีใครพูดกับผมแบบนี้มานาน']:['เขาพยักหน้า ไม่เร่ง รอให้ผมพูดต่อ\\nผมไม่ได้พูด เขาก็ไม่ว่าอะไร']);",
    "await say(a===0?['\"สามสิบปี\" เขาทวน \"งั้นคุณปู่รู้จักตึกนี้ดีกว่าใครเลยนะครับ\"']:['เขาพยักหน้า ไม่เร่ง รอให้ผมพูดต่อ ผมไม่ได้พูด เขาก็ไม่ว่าอะไร']);")
sub("if(a===0){ S.honest++; await say(['\"ประหยัดแรงดีนะครับ\" เขาว่า แล้วจดลงสมุด\\nผมรอคำว่า แต่ มันยังไม่มา']); } else await say(['เขาจดลงไป\\nหม้อข้าวต้มหลังกระติกน้ำ เหมือนมันกำลังมองหลังผมอยู่']);",
    "if(a===0){ S.honest++; await say(['\"ประหยัดแรงดีนะครับ\" เขาจดลงสมุด ผมรอคำว่า แต่ มันยังไม่มา']); } else await say(['เขาจดลงไป หม้อข้าวต้มหลังกระติกน้ำเหมือนกำลังมองหลังผมอยู่']);")
sub("await say(['เขามองไปทางประตู\\n\"ห้องน้ำอยู่ไกลเหมือนกันนะครับ ผมเดินขึ้นมาสี่ชั้นยังเหนื่อยเลย คุณปู่เดินทุกวัน เก่งมากครับ\"', a===0?'เขาฟัง แล้วเขาก็เห็นภาพ\\nไม่ได้ฟังเพื่อจะจด':'เขาไม่ได้บอกว่าผมโกหก\\nเขาแค่บอกว่า เขาเห็น']); trust(1);",
    "await say(['\"ห้องน้ำอยู่ไกลเหมือนกันนะครับ ผมเดินขึ้นมาสี่ชั้นยังเหนื่อยเลย คุณปู่เดินทุกวัน เก่งมากครับ\"\\n'+(a===0?'เขาฟังแล้วเห็นภาพ ไม่ได้ฟังเพื่อจะจด':'เขาไม่ได้บอกว่าผมโกหก เขาแค่บอกว่า เขาเห็น')]); trust(1);")
sub("await say(['ผมมองไปที่หน้าต่าง\\nสะโพกซ้ายเต้นตุบๆ อยู่ใต้กางเกง','เด็กคนนั้นมองตามสายตาผม แล้วมองกลับมา\\nเขาไม่ได้จดอะไรลงสมุด','\"คุณปู่ครับ เรื่องที่คุณปู่เล่าให้ผมฟังวันนี้ ผมจะใช้เพื่อดูแลเรื่องยาเท่านั้น\\nถ้าจะต้องบอกใคร ผมจะถามคุณปู่ก่อนทุกครั้ง\"','เขาพูดเหมือนอ่านใจผมออก\\nหรือไม่ก็ มีคนสอนเขามาดี']); trust(1);",
    "await say(['ผมมองไปที่หน้าต่าง สะโพกซ้ายเต้นตุบๆ อยู่ใต้กางเกง\\nเด็กคนนั้นมองตามสายตาผม แล้วไม่ได้จดอะไรลงสมุด','\"เรื่องที่คุณปู่เล่าวันนี้ ผมจะใช้ดูแลเรื่องยาเท่านั้นครับ ถ้าจะต้องบอกใคร ผมจะถามคุณปู่ก่อน\"\\nเขาพูดเหมือนอ่านใจผมออก หรือไม่ก็ มีคนสอนเขามาดี']); trust(1);")
sub("await say(['เขาเหลือบดูสมุด แล้วถามเร็วไปหน่อย\\n\"ทำไมคุณปู่ไม่ใช้อันสีเขียวล่ะครับ\"','ทำไม\\nคำนี้ผมได้ยินจากครูฝึก จากหมอ จากทุกคนที่ถือแฟ้ม หลังคำนี้จะตามด้วยความผิดของผมเสมอ']); trust(-1);",
    "await say(['เขาเหลือบดูสมุด แล้วถามเร็วไปหน่อย \"ทำไมคุณปู่ไม่ใช้อันสีเขียวล่ะครับ\"\\nทำไม หลังคำนี้จะตามด้วยความผิดของผมเสมอ']); trust(-1);")
sub("await say(['เภสัชกรเฉินกระแอมเบาๆ หนึ่งที\\nเด็กคนนั้นวางปากกาลง','\"ขอโทษครับ ผมถามไม่ดี ขอถามใหม่นะครับ\\nอันสีเขียว เวลาคุณปู่ใช้ รู้สึกยังไงบ้างครับ\"','\"กดแล้วไม่รู้สึกอะไร\" ผมตอบได้ทันที\\nคำถามเดียวกัน แต่คราวนี้มันเป็นคำถามจริงๆ']); trust(1);",
    "await say(['เภสัชกรเฉินกระแอมเบาๆ เด็กคนนั้นวางปากกาลง\\n\"ขอโทษครับ ผมถามไม่ดี อันสีเขียว เวลาคุณปู่ใช้ รู้สึกยังไงบ้างครับ\"','\"กดแล้วไม่รู้สึกอะไร\" ผมตอบได้ทันที\\nคำถามเดียวกัน แต่คราวนี้มันเป็นคำถามจริงๆ']); trust(1);")
sub("await say(['\"ก่อนจะคุยเรื่องยา ผมอยากรู้ก่อนครับ ว่าคุณปู่หวังอะไร\"','ผมรอคำถามข้อต่อไป\\nไม่มี เขารอคำตอบจริงๆ','คนสุดท้ายที่ถามผมแบบนี้ คือแม่ ที่ชิงเต่า\\nผมสิบห้า ผมตอบว่า อยากมีรองเท้าหนังสักคู่','สามเดือนต่อมา กองทัพให้รองเท้าหนังผมหนึ่งคู่\\nแล้วผมก็ไม่ได้กลับบ้านอีกเลย ตั้งแต่นั้นผมก็ไม่หวังอะไรอีก']);",
    "await say(['\"ก่อนจะคุยเรื่องยา ผมอยากรู้ก่อนครับ ว่าคุณปู่หวังอะไร\"\\nผมรอคำถามข้อต่อไป ไม่มี เขารอคำตอบจริงๆ','คนสุดท้ายที่ถามผมแบบนี้คือแม่ ที่ชิงเต่า ผมสิบห้า ผมตอบว่า อยากมีรองเท้าหนังสักคู่\\nสามเดือนต่อมา กองทัพให้รองเท้าหนังผมหนึ่งคู่ แล้วผมก็ไม่ได้กลับบ้านอีกเลย']);")
sub("if(h===2) await say(['\"ไม่เป็นไรครับ งั้นเอาเรื่องเล็กที่สุดก่อน\\nถ้าพรุ่งนี้ทำได้หนึ่งอย่าง คุณปู่อยากทำอะไร\"','ผมมองเจ้าดำ\\nเด็กคนนั้นมองตาม แล้วยิ้ม']);",
    "if(h===2) await say(['\"งั้นเอาเรื่องเล็กที่สุดครับ ถ้าพรุ่งนี้ทำได้หนึ่งอย่าง คุณปู่อยากทำอะไร\"\\nผมมองเจ้าดำ เด็กคนนั้นมองตาม แล้วยิ้ม']);")
sub("if(h===1) await say(['\"ภาระ\" เภสัชกรเฉินทวนคำนั้นช้าๆ\\n\"ปีที่แล้วคุณปู่ไปหาหมอเก้าสิบสามครั้ง ลงบันไดสี่ชั้นเองทุกครั้ง คนที่เป็นภาระ ทำแบบนั้นไม่ได้หรอกครับ\"','ผมไม่เคยมองเลขเก้าสิบสามแบบนั้นมาก่อน']);",
    "if(h===1) await say(['\"ภาระ\" เภสัชกรเฉินทวนช้าๆ \"ปีที่แล้วคุณปู่ลงบันไดสี่ชั้นไปหาหมอเองเก้าสิบสามครั้ง คนที่เป็นภาระทำแบบนั้นไม่ได้หรอกครับ\"']);")
sub("await say(['เด็กคนนั้นจดลงสมุด ตัวโต ขีดเส้นใต้สองเส้น\\n\"งั้นยาทุกตัวต่อจากนี้ ต้องตอบให้ได้ ว่ามันช่วยให้คุณปู่ลงบันไดสี่ชั้นหรือเปล่า\"']); trust(1);\n  await say(['ผมตอบไปหลายข้อแล้ว เริ่มเหนื่อย\\nเขาเห็นก่อนที่ผมจะพูด \"พักดื่มน้ำก่อนไหมครับ เราไม่รีบ\"']);",
    "await say(['เด็กคนนั้นจดตัวโต ขีดเส้นใต้สองเส้น\\n\"งั้นยาทุกตัวต่อจากนี้ ต้องตอบให้ได้ ว่ามันช่วยให้คุณปู่ลงบันไดสี่ชั้นหรือเปล่า\"']); trust(1);")
sub("await say(['\"คุณปู่ครับ ผมขออนุญาตดูรอบๆ ห้องได้ไหมครับ\\nดูว่ายาเก็บไว้ตรงไหน ห้องร้อนไหม เดินสะดวกไหม\"']);",
    "await say(['\"ผมขออนุญาตดูรอบๆ ห้องได้ไหมครับ ว่ายาเก็บไว้ตรงไหน ห้องร้อนไหม เดินสะดวกไหม\"']);")
sub("const no=async(own)=>{ S.refuse++; await say(['\"ได้ครับ\" เขาถอยมือกลับทันที\\nผมลองปฏิเสธดูเฉยๆ อยากรู้ว่าเขาจะหยุดจริงไหม','เขาหยุดจริง']); trust(1); await say([own]); };",
    "const no=async(own)=>{ S.refuse++; await say(['\"ได้ครับ\" เขาถอยมือกลับทันที\\nผมลองปฏิเสธดูเฉยๆ อยากรู้ว่าเขาจะหยุดจริงไหม เขาหยุดจริง']); trust(1); await say([own]); };")
sub("await say(['เขาเขย่าอันสีฟ้าเบาๆ ข้างหู \"ใกล้หมดแล้วนะครับ\"\\nแล้วหยิบอันสีเขียว \"อันนี้ยังเกือบเต็ม\"','เขาไม่ได้พูดว่า ใช้ผิด\\nเขาวางคืนที่เดิม หันหน้าออกเหมือนเดิม']);",
    "await say(['เขาเขย่าอันสีฟ้าข้างหู \"ใกล้หมดแล้วนะครับ\" อันสีเขียว \"ยังเกือบเต็ม\"\\nเขาไม่ได้พูดว่า ใช้ผิด เขาวางคืนที่เดิม']);")
sub("await say(['เขายืนดูปฏิทินอยู่นาน ไม่ได้แตะ\\n\"คุณปู่จดเองหมดเลยเหรอครับ สัปดาห์ละสองสามนัด ไม่เคยพลาดเลย\"','\"มีวงหนึ่งถูกขีดฆ่า\" เขาชี้ \"นัดหมอผิวหนังเดือนที่แล้ว\"\\n\"วันนั้นลงบันไดไม่ไหว\" ผมตอบ ก่อนจะทันคิดว่าควรตอบไหม','เขาไม่ได้พูดว่า ไปหาหมอเยอะเกินไป\\nเขาพูดว่า \"วงพวกนี้ คือวันที่คุณปู่ได้ออกไปเจอคน ใช่ไหมครับ\"']); trust(1);",
    "await say(['เขายืนดูปฏิทินอยู่นาน \"มีวงหนึ่งถูกขีดฆ่า\"\\n\"วันนั้นลงบันไดไม่ไหว\" ผมตอบ ก่อนจะทันคิดว่าควรตอบไหม','เขาไม่ได้พูดว่า ไปหาหมอเยอะเกินไป\\nเขาพูดว่า \"วงพวกนี้ คือวันที่คุณปู่ได้ออกไปเจอคน ใช่ไหมครับ\"']); trust(1);")
sub("if(await YN()===1) await no('ผมเลื่อนกระติกน้ำออกเอง'); else await say(['เขาเลื่อนกระติกน้ำ\\nหม้อข้าวต้มอยู่ตรงนั้น ที่ที่ผมซ่อนมันไว้เมื่อเช้า']);\n  await say(['เขาเปิดฝาขึ้นนิดเดียว ไม่ได้ย่นจมูก\\n\"ต้มไว้ตั้งแต่เมื่อไรครับ\"','\"…วันอาทิตย์\"','\"หกวันแล้วนะครับ อากาศร้อนแบบนี้เชื้อโตเร็ว ต้มซ้ำก็ทำลายพิษได้ไม่หมด ผมเป็นห่วงท้องคุณปู่\"\\nครูฝึกสอนผมว่าความร้อนฆ่าได้ทุกอย่าง ครูฝึกไม่ใช่เภสัชกร','\"ต้มหม้อเล็กลง พอกินวันต่อวัน ได้ไหมครับ วันที่ไม่ไหว เราจะลองถามเรื่องบริการส่งอาหารให้\"\\nเขาไม่ได้สั่งให้ผมเททิ้ง เขาถามผมว่า ได้ไหม']);",
    "if(await YN()===1) await no('ผมเลื่อนกระติกน้ำออกเอง');\n  await say(['หม้อข้าวต้มอยู่ตรงนั้น เขาเปิดฝานิดเดียว ไม่ได้ย่นจมูก \"ต้มไว้ตั้งแต่เมื่อไรครับ\" \"…วันอาทิตย์\"\\n\"อากาศร้อนแบบนี้เชื้อโตเร็ว ต้มซ้ำก็ทำลายพิษได้ไม่หมดครับ\" ครูฝึกไม่ใช่เภสัชกร','\"ต้มหม้อเล็กลง พอกินวันต่อวัน ได้ไหมครับ\"\\nเขาไม่ได้สั่งให้ผมเททิ้ง เขาถามผมว่า ได้ไหม']);")
sub("await say(['สมุดบัญชี ใบเสร็จ ใบปลิว \"บำรุงเข่า บำรุงตา\" แล้วก็ขวดนั้น\\nเขาหยิบขวดขึ้นมาอ่านฉลาก ไม่ได้ส่ายหัว','\"คุณปู่ซื้อเองเหรอครับ อยากให้เข่าดีขึ้น\"\\n\"…อย่าบอกอาเหมย\"','\"ผมไม่บอกครับ ผมสัญญาไว้แล้ว\" เขาวางขวดคืนที่เดิม\\n\"ตัวนี้ไม่ได้ตีกับยาของคุณปู่ครับ แต่หลักฐานว่าช่วยเข่าได้มีไม่มาก และเดือนหนึ่งเท่ากับค่าข้าวหลายมื้อ\"','\"เข่าที่อยากให้ดี คุณปู่อยากเอาไปทำอะไรครับ\"\\nผมไม่ได้ตอบ ผมมองไปที่วิทยุ']); cardOff();",
    "await say(['เขาหยิบขวดบำรุงเข่าขึ้นมาอ่านฉลาก ไม่ได้ส่ายหัว \"คุณปู่ซื้อเองเหรอครับ\"\\n\"…อย่าบอกอาเหมย\" \"ผมไม่บอกครับ ผมสัญญาไว้แล้ว\"','\"ตัวนี้ไม่ตีกับยาของคุณปู่ แต่หลักฐานว่าช่วยเข่ามีไม่มาก เข่าที่อยากให้ดี คุณปู่อยากเอาไปทำอะไรครับ\"\\nผมไม่ได้ตอบ ผมมองไปที่วิทยุ']); cardOff();")
sub("await say(['มือเขาเอื้อมไปที่ลิ้นชัก\\nไหล่ผมแข็งขึ้นมาเอง','เขาเห็น มือเขาหยุดกลางอากาศ\\n\"ขอโทษครับ ลิ้นชักนี้ ผมขอเปิดได้ไหมครับ\"']);",
    "await say(['มือเขาเอื้อมไปที่ลิ้นชัก ไหล่ผมแข็งขึ้นมาเอง\\nเขาเห็น มือหยุดกลางอากาศ \"ขอโทษครับ ลิ้นชักนี้ ผมขอเปิดได้ไหมครับ\"']);")
sub("if(await YN()===1){ S.refuse++; await say(['\"ได้ครับ ไม่เป็นไรเลย\" เขาถอยออกมานั่งที่เดิม','ผมนั่งมองลิ้นชักอยู่ครู่หนึ่ง\\nแล้วก็ลุกไปเปิดมันเอง ไม่รู้เหมือนกันว่าทำไม']); } else await say(['ผมพยักหน้า\\nสิ่งที่ผมซ่อนไว้เมื่อเช้า ผมยอมให้เขาเปิดตอนบ่าย']); trust(1);",
    "if(await YN()===1){ S.refuse++; await say(['\"ได้ครับ ไม่เป็นไรเลย\" เขาถอยออกมา\\nผมนั่งมองลิ้นชักครู่หนึ่ง แล้วลุกไปเปิดมันเอง ไม่รู้เหมือนกันว่าทำไม']); } else await say(['สิ่งที่ผมซ่อนไว้เมื่อเช้า ผมยอมให้เขาเปิดตอนบ่าย']); trust(1);")
sub("await say(['สิบสามซอง เรียงบนผ้าห่ม\\nเด็กคนนั้นไม่ได้อุทาน ไม่ได้ถอนหายใจ เขาแค่เริ่มจับคู่','\"ซองนี้ คุณปู่อ่านออกไหมครับ ว่าให้กินตอนไหน\"']);",
    "await say(['สิบสามซองเรียงบนผ้าห่ม เขาไม่ได้อุทาน เขาแค่เริ่มจับคู่\\n\"ซองนี้ คุณปู่อ่านออกไหมครับ ว่าให้กินตอนไหน\"']);")
sub("await say(['ตัวหนังสือเท่ามด ต่อให้เพ่งก็เห็นแค่เส้นหยัก\\n\"ผมอ่านไม่ออก\" ผมพูดออกไปแล้ว ก่อนจะทันอาย','\"ผมเองยังต้องเพ่งเลยครับ ไม่ใช่ตาคุณปู่หรอก ฉลากมันเล็กเกินไป\"']); trust(1);\n  await say(['\"สองซองนี้เป็นยาแก้แพ้เหมือนกันครับ มาจากคุณหมอคนละท่าน\\nกินด้วยกันจะง่วงมาก ทรงตัวลำบาก โดยเฉพาะตอนลุกกลางดึก\"','ผมนึกถึงกระเบื้องเย็นๆ','\"ไม่ใช่ความผิดของคุณปู่นะครับ คุณหมอแต่ละท่านมองไม่เห็นซองของอีกท่าน\\nพวกผมมีหน้าที่มองให้เห็นครบทุกซอง\"']); cardOff();",
    "await say(['\"ผมอ่านไม่ออก\" ผมพูดออกไปแล้ว ก่อนจะทันอาย\\n\"ผมเองยังต้องเพ่งเลยครับ ฉลากมันเล็กเกินไป\"']); trust(1);\n  await say(['\"สองซองนี้เป็นยาแก้แพ้เหมือนกัน จากคุณหมอคนละท่าน กินด้วยกันจะง่วง ทรงตัวลำบาก โดยเฉพาะตอนลุกกลางดึก\"\\nผมนึกถึงกระเบื้องเย็นๆ','\"ไม่ใช่ความผิดของคุณปู่นะครับ คุณหมอแต่ละท่านมองไม่เห็นซองของอีกท่าน พวกผมมีหน้าที่มองให้เห็นครบ\"']); cardOff();")
sub("await say(['เด็กคนนั้นหยิบของออกจากกระเป๋า\\nยาพ่นสีฟ้า กับกระบอกใสยาวราวหนึ่งคืบ']);\n  card('spacer');\n  await say(['\"อันสีฟ้า คุณปู่กดแล้วสูดตามไม่ทันใช่ไหมครับ ยาเลยไปค้างที่คอ ขม แล้วก็ไอ\"\\nเขารู้ได้ยังไง','\"ไม่ต้องแข่งกับมันแล้วครับ ต่อกระบอกนี้ ยาจะรออยู่ข้างใน\\nลองนะครับ เขย่าก่อน สี่ห้าที\"']);",
    "card('spacer');\n  await say(['\"อันสีฟ้า คุณปู่กดแล้วสูดตามไม่ทันใช่ไหมครับ ยาเลยค้างที่คอ ขม แล้วก็ไอ\" เขารู้ได้ยังไง\\n\"ต่อกระบอกนี้ ยาจะรออยู่ข้างใน ลองนะครับ เขย่าก่อน สี่ห้าที\"']);")
sub("await say(['ไม่ขม ไม่ไอ\\nหลายปีที่ผมสู้กับหลอดสีฟ้านี่ มันแค่ต้องการกระบอกพลาสติกหนึ่งอัน']);",
    "await say(['ไม่ขม ไม่ไอ\\nหลายปีที่ผมสู้กับหลอดสีฟ้านี่ มันแค่ต้องการกระบอกพลาสติกหนึ่งอัน']);")
sub("await say(['\"ส่วนอันสีเขียว ที่คุณปู่ว่ากดแล้วไม่รู้สึกอะไร\"\\n\"ถูกแล้วครับ มันไม่ได้มีไว้ให้รู้สึก\"','\"อันสีฟ้าคือหน่วยเคลื่อนที่เร็ว เรียกเมื่อไรมาเมื่อนั้น\\nอันสีเขียวคือยามกะดึก ยืนเงียบๆ ทั้งคืน ถ้ายามทำงานดี คุณปู่แทบไม่ต้องเรียกหน่วยเคลื่อนที่เร็วเลย\"','ยามกะดึก\\nผมเป็นยามกะดึกมาสี่ปี ไม่เคยมีใครขอบใจ จนกว่าจะมีคืนที่ยามหลับ']); trust(1); cardOff();",
    "await say(['\"อันสีเขียวที่กดแล้วไม่รู้สึกอะไร ถูกแล้วครับ มันไม่ได้มีไว้ให้รู้สึก\"\\n\"อันสีฟ้าคือหน่วยเคลื่อนที่เร็ว อันสีเขียวคือยามกะดึก ยืนเงียบๆ ทั้งคืน ถ้ายามทำงานดี แทบไม่ต้องเรียกหน่วยเคลื่อนที่เร็วเลย\"','ยามกะดึก\\nผมเป็นยามกะดึกมาสี่ปี ไม่เคยมีใครขอบใจ จนกว่าจะมีคืนที่ยามหลับ']); trust(1); cardOff();")
sub("await say(['\"อันนี้ไม่ต้องเขย่าครับ ผมทำให้ดูก่อน ช้าๆ\"\\nหมุนฐาน… เปิดฝา… อม… แล้วกดพร้อมกับเริ่มสูด','เขามองตาผมตลอด ว่าผมตามทันไหม\\nไม่ได้มองนาฬิกา']);",
    "await say(['\"อันนี้ไม่ต้องเขย่าครับ ผมทำให้ดูก่อน\" หมุนฐาน… เปิดฝา… อม… กดพร้อมเริ่มสูด\\nเขามองตาผมตลอด ว่าผมตามทันไหม ไม่ได้มองนาฬิกา']);")
sub("await say(['ไม่รู้สึกอะไรเหมือนเดิม\\nแต่คราวนี้ผมรู้แล้ว ว่าความเงียบแบบนี้ แปลว่ายามยังตื่นอยู่','\"ครั้งละสองพัฟ วันละครั้ง ตอนเช้าครับ คือทำแบบเมื่อกี้สองรอบ\"']); cardOff();",
    "await say(['ไม่รู้สึกอะไรเหมือนเดิม แต่คราวนี้ผมรู้แล้ว ความเงียบแบบนี้แปลว่ายามยังตื่นอยู่\\n\"ครั้งละสองพัฟ วันละครั้ง ตอนเช้าครับ\"']); cardOff();")
sub("await say(['\"คุณปู่ครับ ผมอธิบายไปเยอะ ไม่แน่ใจว่าผมอธิบายรู้เรื่องไหม\\nรบกวนคุณปู่ทำให้ผมดูอีกรอบได้ไหมครับ คราวนี้ผมจะไม่บอกอะไรเลย\"','เขาไม่ได้พูดว่า จะทดสอบผม\\nเขาพูดว่า จะตรวจว่าตัวเขาเองสอนรู้เรื่องไหม']);",
    "await say(['\"ผมไม่แน่ใจว่าอธิบายรู้เรื่องไหม รบกวนคุณปู่ทำให้ผมดูอีกรอบได้ไหมครับ คราวนี้ผมจะไม่บอกอะไรเลย\"\\nเขาไม่ได้พูดว่าจะทดสอบผม เขาพูดว่าจะตรวจว่าตัวเขาเองสอนรู้เรื่องไหม']);")
sub("await say(['เด็กคนนั้นยิ้มกว้างจนตาหยี \"ถูกหมดเลยครับ\"', S.tbErr?'ผมพลาดไป '+S.tbErr+' ครั้ง เขาไม่ได้นับ\\nผมนับเอง':'ทหารแก่เรียนท่าใหม่ได้\\nถ้าครูฝึกไม่ตะคอก']); trust(1);",
    "await say(['เด็กคนนั้นยิ้มจนตาหยี \"ถูกหมดเลยครับ\"\\n'+(S.tbErr?'ผมพลาดไป '+S.tbErr+' ครั้ง เขาไม่ได้นับ ผมนับเอง':'ทหารแก่เรียนท่าใหม่ได้ ถ้าครูฝึกไม่ตะคอก')]); trust(1);")
sub("await say(['เขาเปิดกล่องยาเจ็ดช่อง มองอยู่ครู่หนึ่ง','\"คุณปู่ครับ วันที่คุณอาเหมยเข้าเวรดึก เช้าวันนั้นเป็นยังไงบ้างครับ\"\\nเขาไม่ได้ถามว่า ลืมกินยาหรือเปล่า','ผมมองอาเหมยที่ยืนอยู่ข้างประตู\\nเธอยังไม่รู้อะไรเลย']);",
    "await say(['เขาเปิดกล่องยาเจ็ดช่อง มองอยู่ครู่หนึ่ง \"วันที่คุณอาเหมยเข้าเวรดึก เช้าวันนั้นเป็นยังไงบ้างครับ\"\\nเขาไม่ได้ถามว่า ลืมกินยาหรือเปล่า ผมมองอาเหมยที่ยืนอยู่ข้างประตู เธอยังไม่รู้อะไรเลย']);")
sub("if(S.tell){ await say(['\"ผมลืม\" ผมได้ยินเสียงตัวเอง\\n\"วันที่ไม่มีใครโทรมา ผมลืม'+(anyDbl?' แล้วผมก็กินรวมทีเดียวตอนกลางคืน\"':' แล้วก็ปล่อยมันข้ามไป\"'),'\"แล้วเมื่อคืน… ผมล้มในห้องน้ำ\"\\nห้องเงียบ ได้ยินแต่เสียงพัดลม','เด็กคนนั้นไม่ได้ตกใจ ไม่ได้ดุ\\nเขาถามว่า \"เจ็บตรงไหนบ้างครับ\"','เจ็บตรงไหนบ้าง\\nไม่ใช่ ทำไมไม่บอก','\"ผมไม่อยากไปอยู่บ้านพัก\" ผมพูด \"ที่นั่นเขาไม่ให้เลี้ยงหมา\"','\"ไม่มีใครส่งคุณปู่ไปไหนทั้งนั้นครับ\" เภสัชกรเฉินพูดช้าๆ\\n\"เรามาเพื่อให้คุณปู่อยู่ห้องนี้ได้นานที่สุด กับเจ้าดำ\"']);",
    "if(S.tell){ await say(['\"วันที่ไม่มีใครโทรมา ผมลืม'+(anyDbl?' แล้วก็กินรวมทีเดียวตอนกลางคืน':' แล้วก็ปล่อยมันข้ามไป')+'\"\\n\"แล้วเมื่อคืนวันพฤหัส… ผมล้มในห้องน้ำ\" ห้องเงียบ ได้ยินแต่เสียงพัดลม','เด็กคนนั้นไม่ได้ดุ เขาถามว่า \"เจ็บตรงไหนบ้างครับ\"\\nเจ็บตรงไหนบ้าง ไม่ใช่ ทำไมไม่บอก','\"ผมไม่อยากไปอยู่บ้านพัก ที่นั่นเขาไม่ให้เลี้ยงหมา\"\\n\"ไม่มีใครส่งคุณปู่ไปไหนทั้งนั้นครับ\" เภสัชกรเฉินพูดช้าๆ \"เรามาเพื่อให้คุณปู่อยู่ห้องนี้ได้นานที่สุด กับเจ้าดำ\"']);")
sub("else await say(['\"ก็ปกติ\" ผมตอบ','เด็กคนนั้นมองกล่องยา แล้วมองผม แล้วปิดฝากล่องเบาๆ\\n\"ไม่เป็นไรครับ วันไหนคุณปู่อยากเล่า ผมจะมาฟัง\"','เขาเขียนเบอร์โทรศัพท์ตัวโตๆ ลงบนกระดาษ วางไว้ข้างโทรศัพท์สีแดง\\nเขาไม่ได้เชื่อผม และเขาไม่ได้บังคับผม ผมไม่เคยเจอสองอย่างนี้พร้อมกัน','\"ระหว่างนี้ วันที่เข้าเวรดึก คุณอาเหมยพอจะโทรจากที่ทำงานได้ไหมครับ\"\\nอาเหมยพยักหน้า แล้วมองผมนานกว่าปกติ']);",
    "else await say(['\"ก็ปกติ\" เด็กคนนั้นปิดฝากล่องเบาๆ \"ไม่เป็นไรครับ วันไหนคุณปู่อยากเล่า ผมจะมาฟัง\"\\nเขาเขียนเบอร์โทรตัวโตๆ วางไว้ข้างโทรศัพท์ เขาไม่ได้เชื่อผม และไม่ได้บังคับผม','\"วันที่เข้าเวรดึก คุณอาเหมยพอจะโทรจากที่ทำงานได้ไหมครับ\"\\nอาเหมยพยักหน้า แล้วมองผมนานกว่าปกติ']);")
sub("await say(['\"ก่อนกลับ รบกวนคุณปู่ช่วยทวนให้ผมฟังหน่อยครับ ว่าต่อจากนี้จะทำยังไงบ้าง\\nผมจะได้รู้ว่าผมพูดครบไหม\"']);",
    "await say(['\"ก่อนกลับ รบกวนคุณปู่ทวนให้ผมฟังหน่อยครับ ว่าต่อจากนี้จะทำยังไง ผมจะได้รู้ว่าพูดครบไหม\"']);")
sub("if(c!==ok){ S.sumErr++; await say(['\"ข้อนี้ผมพูดไม่ชัดเองครับ\" เขาว่า แล้วอธิบายใหม่ ช้ากว่าเดิม\\nเขารับความผิดไปเอง ทั้งที่คนพลาดคือผม'].concat(fix?[fix]:[])); } else if(fix) await say(['\"ครบเลยครับ\"']);",
    "if(c!==ok){ S.sumErr++; await say(['\"ข้อนี้ผมพูดไม่ชัดเองครับ\" เขารับความผิดไปเอง ทั้งที่คนพลาดคือผม'+(fix?'\\n'+fix:'')]); }")
sub("if(!fix) await say(['\"ยาเบาหวานตัวนั้น ถ้ากินสองมื้อรวมกัน น้ำตาลจะตกตอนกลางดึกครับ เหงื่อแตก มือสั่น ใจสั่น หน้ามืด\\nนึกได้ตอนค่ำ ให้ข้ามไปเลย พรุ่งนี้เริ่มใหม่\"', anyDbl?'เหงื่อแตก มือสั่น ใจสั่น\\nผมนึกมาตลอดว่ามันคือฝันร้าย':'ยาของหลวง ทิ้งไม่ได้ ผมถูกฝึกมาอย่างนั้น\\nวันนี้มีคนบอกผมว่า บางคำสั่ง เลิกเชื่อฟังได้']); }",
    "if(!fix) await say(['\"ยาเบาหวานตัวนั้น ถ้ากินสองมื้อรวมกัน น้ำตาลจะตกตอนกลางดึก เหงื่อแตก มือสั่น ใจสั่น นึกได้ตอนค่ำให้ข้ามไปเลยครับ\"\\n'+(anyDbl?'เหงื่อแตก มือสั่น ใจสั่น ผมนึกมาตลอดว่ามันคือฝันร้าย':'ยาของหลวง ทิ้งไม่ได้ วันนี้มีคนบอกผมว่า บางคำสั่งเลิกเชื่อฟังได้')]); }")
sub("await say(['เด็กคนนั้นแปะกระดาษแผ่นหนึ่งไว้ข้างเตียง\\nพระอาทิตย์ ชามข้าว พระจันทร์ จุดสีดวงใหญ่ ไม่มีตัวหนังสือเล็กสักตัว','ผมเคยเห็นแผ่นแบบนี้มาก่อน\\nบนซองยาเก่าก้นลิ้นชัก ลายมืออาเหมย ซองที่เราทะเลาะกัน เด็กคนนี้ไม่มีทางรู้','พระอาทิตย์กับพระจันทร์ไม่ได้ดูถูกใคร\\nมันแค่อ่านง่าย ผมใช้เวลาสิบเจ็ดปีกว่าจะยอมรับ','\"ยาจะเหลือน้อยกว่านี้ครับ ผมจะเขียนถึงคุณหมอทั้งสี่ท่าน\\nให้แต่ละท่านรู้ ว่ามีอีกสามท่าน\"']); cardOff();",
    "await say(['เขาแปะกระดาษไว้ข้างเตียง พระอาทิตย์ ชามข้าว พระจันทร์ จุดสีดวงใหญ่ ไม่มีตัวหนังสือเล็กสักตัว\\nเหมือนซองยาเก่าก้นลิ้นชัก ลายมืออาเหมย ซองที่เราทะเลาะกัน','พระอาทิตย์กับพระจันทร์ไม่ได้ดูถูกใคร มันแค่อ่านง่าย\\nผมใช้เวลาสิบเจ็ดปีกว่าจะยอมรับ','\"ยาจะเหลือน้อยกว่านี้ครับ ผมจะเขียนถึงคุณหมอทั้งสี่ท่าน ให้แต่ละท่านรู้ว่ามีอีกสามท่าน\"']); cardOff();")
sub("await say(['\"อาทิตย์หน้าผมมาใหม่นะครับ\"\\nผมเกือบถามว่า กี่โมง จะได้นั่งรอ','ประตูปิด\\nห้องกลับมาสิบหกตารางเมตรเท่าเดิม แต่ไม่เงียบเท่าเดิม']);",
    "await say(['\"อาทิตย์หน้าผมมาใหม่นะครับ\" ผมเกือบถามว่า กี่โมง จะได้นั่งรอ\\nประตูปิด ห้องสิบหกตารางเมตรเท่าเดิม แต่ไม่เงียบเท่าเดิม']);")
sub("await say(['สี่โมงเย็น วิทยุยังตั้งคลื่นค้างไว้จากวันอังคาร','…เพลงนี้\\nสามนาทีสิบวินาที','เข่าผมไม่ดี สะโพกผมช้ำ\\nเจ้าดำมองหน้าผม']);",
    "await say(['สี่โมงเย็น …เพลงนี้ สามนาทีสิบวินาที\\nเข่าผมไม่ดี สะโพกผมช้ำ เจ้าดำมองหน้าผม']);")
sub("await say(['สิบวินาที\\nเจ้าดำเหยียบเท้าผมสองครั้ง ผมเหยียบเท้ามันหนึ่งครั้ง','แม่\\nผมมาช้าไปเจ็ดสิบสี่ปี','แต่ผมมาแล้ว']);",
    "await say(['สิบวินาที เจ้าดำเหยียบเท้าผมสองครั้ง ผมเหยียบเท้ามันหนึ่งครั้ง','แม่\\nผมมาช้าไปเจ็ดสิบสี่ปี แต่ผมมาแล้ว']);")
sub("await say(['คืนนี้ผมใช้อันสีเขียวก่อนนอนอีกรอบ ไม่ใช่เพราะถึงเวลา\\nผมแค่อยากหมุนให้ดังคลิก ให้แน่ใจว่ายังจำได้','ผมวางตะเกียบสองคู่ และไม่ได้เก็บ\\nคืนนี้ผมมีเรื่องจะรายงานแม่เยอะ']);",
    "await say(['คืนนี้ผมวางตะเกียบสองคู่ และไม่ได้เก็บ\\nผมมีเรื่องจะรายงานแม่เยอะ']);")
